#!/usr/bin/env python3
"""pbp: a process behaviour policy, derived from one traced run and enforced by Linux.

  pbp.py trace NAME [--write DIR] [--host HOST] -- CMD...   derive NAME.pbp.json from an strace run
  pbp.py run NAME [--probe] [--cmd ...]                     run CMD under the policy, with timings
"""
import shlex, json, os, re, subprocess, sys, time, random, shutil, socket, threading, select

HERE = os.path.dirname(os.path.abspath(__file__))
UNISTD = '/usr/include/x86_64-linux-gnu/asm/unistd_64.h'
NR = {m[1]: int(m[2]) for m in re.finditer(r'#define __NR_(\w+)\s+(\d+)', open(UNISTD).read())}
SKIP = ('/proc/', '/sys/', '/dev/')  # handled as mounts, not files

def trace(name, cmd, writes, hosts, envs=()):
    log = f'/tmp/pbp-{name}.strace'
    t = time.time()
    subprocess.run(['strace', '-f', '-qq', '-s', '256', '-o', log, *cmd], check=False)
    traced = time.time() - t
    files, dirs, execs, sys_used, conns, devs, procfs = set(), set(), [], set(), set(), set(), False
    pat = re.compile(r'^\d+\s+(\w+)\((.*)\)\s+=\s+(-?\d+|\?)')
    pending = {}
    for line in open(log):
        u = re.match(r'^(\d+)\s+(\w+)\((.*) <unfinished \.\.\.>$', line.rstrip())
        if u: pending[u[1]] = (u[2], u[3]); continue
        r = re.match(r'^(\d+)\s+<\.\.\. (\w+) resumed>(.*)$', line.rstrip())
        if r and r[1] in pending:
            call, args = pending.pop(r[1]); line = f'{r[1]} {call}({args}{r[3]}'
        m = pat.match(line)
        if not m: 
            m2 = re.match(r'^\d+\s+(\w+)\(', line)
            if m2: sys_used.add(m2[1])
            continue
        call, args, rc = m[1], m[2], m[3]
        sys_used.add(call)
        if call == 'connect' and 'EINPROGRESS' in line: rc = '0'
        if rc == '?' or rc.startswith('-'): continue
        for p in re.findall(r'"(/[^"]*)"', args):
            if p.startswith('/proc'): procfs = True; continue
            if p.startswith('/dev/'): devs.add(p); continue
            if p.startswith('/sys/'): continue
            if any(p == w or p.startswith(w.rstrip('/') + '/') for w in writes): continue
            if call == 'execve': execs.append(p)
            if os.path.isdir(p): dirs.add(p)
            elif os.path.exists(p): files.add(p)
        if call == 'connect':
            a = re.search(r'sin_port=htons\((\d+)\).*inet_addr\("([\d.]+)"\)', args)
            if a: conns.add(f'{a[2]}:{a[1]}')
    interps = set()
    # the kernel loads each executable's ELF interpreter itself, so strace never shows it opened
    for e in list(execs) + [shutil.which(cmd[0]) or cmd[0]]:
        with open(e, 'rb') as fh: head = fh.readline(200)
        if head.startswith(b'#!'):  # a script: its interpreter is executed too
            it = head[2:].split()[0].decode(); execs.append(it); files.add(it); e = os.path.realpath(it); files.add(e); execs.append(e)
        out = subprocess.run(['readelf', '-l', e], capture_output=True, text=True).stdout
        m = re.search(r'interpreter: ([^\]]+)\]', out)
        if m: files.add(m[1]); interps.add(m[1])
    # a symlinked file needs its target too (bind mounts resolve the link)
    for f in list(files):
        r = os.path.realpath(f)
        if r != f and os.path.isfile(r): files.add(r)
    exe = shutil.which(cmd[0]) or cmd[0]
    execs = sorted(set(execs) | interps | {os.path.realpath(i) for i in interps} | {os.path.realpath(exe)} | ({exe} if os.path.exists(exe) else set()))
    size = sum(os.path.getsize(f) for f in files if os.path.isfile(f))
    pol = {
        'pbp': 'v0.1', 'name': name, 'command': cmd,
        'derived_from': {'tool': 'strace -f', 'seconds': round(traced, 2), 'log_lines': sum(1 for _ in open(log))},
        'identity': {'user': 'ephemeral', 'groups': [], 'capabilities': [], 'no_new_privs': True},
        'filesystem': {'root': 'empty, read-only', 'read': sorted(files), 'list': sorted(dirs),
                       'write': sorted(writes), 'devices': sorted(devs), 'proc': procfs,
                       'files': len(files), 'bytes': size},
        'exec': execs,
        'network': {'mode': 'broker' if hosts else 'none', 'hosts': hosts, 'seen': sorted(conns)},
        'syscalls': sorted(s for s in sys_used if s in NR),
        'processes': {'see_others': False, 'signal_others': False, 'trace_others': False},
        'environment': {k: os.environ[k] for k in envs if k in os.environ},
        'limits': {'pids': 64, 'memory_mb': 512, 'seconds': 120},
    }
    json.dump(pol, open(os.path.join(HERE, f'{name}.pbp.json'), 'w'), indent=1)
    print(f'{name}: {len(files)} files ({size/1e6:.1f} MB), {len(dirs)} dirs, {len(execs)} executables, '
          f'{len(pol["syscalls"])} syscalls, devices {sorted(devs)}, proc {procfs}, connects {sorted(conns)}; traced in {traced:.2f}s')

class Broker(threading.Thread):
    """the network broker: an HTTP CONNECT proxy that opens tunnels only to the policy's hosts"""
    def __init__(self, hosts):
        super().__init__(daemon=True); self.hosts = set(hosts); self.log = []
        self.s = socket.socket(); self.s.bind(('127.0.0.1', 0)); self.s.listen(16); self.port = self.s.getsockname()[1]
    def run(self):
        while True:
            c, _ = self.s.accept(); threading.Thread(target=self.handle, args=(c,), daemon=True).start()
    def handle(self, c):
        req = c.recv(4096).decode('latin1', 'replace'); m = re.match(r'CONNECT ([^:\s]+):(\d+)', req)
        if not m or m[1] not in self.hosts or m[2] != '443':
            self.log.append(('refused', m[1] if m else req[:40])); c.sendall(b'HTTP/1.1 403 Forbidden\r\n\r\n'); c.close(); return
        self.log.append(('allowed', m[1]))
        u = socket.create_connection((m[1], 443), timeout=20); c.sendall(b'HTTP/1.1 200 Connection established\r\n\r\n')
        socks = [c, u]
        while True:
            r, _, _ = select.select(socks, [], [], 30)
            if not r: break
            for s in r:
                d = s.recv(65536)
                if not d: c.close(); u.close(); return
                (u if s is c else c).sendall(d)

def sh(*a, **k): return subprocess.run(a, check=True, capture_output=True, text=True, **k)

def run(name, probe=False, cmd=None, off=()):
    pol = json.load(open(os.path.join(HERE, f'{name}.pbp.json')))
    cmd = cmd or pol['command']; fs = pol['filesystem']; T = {}
    t = time.time(); user = f'pbp-{name[:8]}-{random.randrange(16**4):04x}'
    sh('useradd', '-r', '-M', '-N', '-d', '/nonexistent', '-s', '/usr/sbin/nologin', user)
    uid = int(sh('id', '-u', user).stdout); gid = 65534; T['ephemeral user'] = time.time() - t
    t = time.time(); broker = None; ipt = []
    if pol['network']['mode'] == 'broker':
        broker = Broker(pol['network']['hosts']); broker.start()
        ipt = [['-o', 'lo', '-d', '127.0.0.1', '-p', 'tcp', '--dport', str(broker.port), '-j', 'ACCEPT'], ['-j', 'REJECT']]
        for r in ipt: sh('iptables', '-A', 'OUTPUT', '-m', 'owner', '--uid-owner', str(uid), *r)
    T['network rules'] = time.time() - t
    t = time.time(); cg = []
    for ctl, k, v in (('pids', 'pids.max', pol['limits']['pids']), ('memory', 'memory.limit_in_bytes', pol['limits']['memory_mb'] << 20)):
        d = f'/sys/fs/cgroup/{ctl}/{user}'; os.mkdir(d); open(f'{d}/{k}', 'w').write(str(v)); cg.append(d)
    T['cgroup limits'] = time.time() - t
    root = f'/tmp/{user}.root'; os.mkdir(root, 0o755)
    exe_args = []
    for p in pol['exec']: exe_args.append(f'rx:{p}')
    for p in fs['read']: exe_args.append(f'ro:{p}')
    for p in fs['list']: exe_args.append(f'ro:{p}')
    for p in fs['devices']: exe_args.append(f'rw:{p}')
    for p in fs['write']: exe_args.append(f'rw:{p}')
    if broker: exe_args.append(f'port:{broker.port}')
    files = sorted(set(fs['read']) | set(pol['exec']) | {f for f in ([HERE + '/probe'] if probe else [])})
    if probe: exe_args.append(f'rx:{HERE}/probe')
    lines = ['set -e', f'mount -t tmpfs -o size=1m,mode=755 pbp {root}']
    for d in sorted(set(fs['list']) | {os.path.dirname(f) for f in files} | {os.path.dirname(f) for f in fs['devices']}):
        lines.append(f'mkdir -p {root}{d}')
    for f in files:
        lines += [f'touch {root}{f}', f'mount --bind {f} {root}{f}', f'mount -o remount,bind,ro {root}{f}']
    for f in fs['devices']:
        lines += [f'touch {root}{f}', f'mount --bind {f} {root}{f}']
    for w in fs['write']:
        lines += [f'mkdir -p {root}{w}', f'mount -t tmpfs -o size=64m,mode=1777 pbpw {root}{w}']
    if fs['proc']: lines += [f'mkdir -p {root}/proc', f'mount -t proc -o hidepid=2 proc {root}/proc']
    lines += [f'mkdir -p {root}/pbp', f'touch {root}/pbp/exec', f'mount --bind {HERE}/pbp-exec {root}/pbp/exec',
              f'mount -o remount,bind,ro {root}', f'for c in {" ".join(cg)}; do echo $$ > $c/cgroup.procs; done']
    sysnums = '-' if 'seccomp' in off else ','.join(str(NR[s]) for s in pol['syscalls'])
    if 'landlock' in off: exe_args.insert(0, 'off:landlock')
    env = {'PATH': '/usr/local/bin:/usr/bin:/bin', 'HOME': '/nonexistent', 'LANG': 'C.UTF-8'}
    if broker: env.update(HTTPS_PROXY=f'http://127.0.0.1:{broker.port}', https_proxy=f'http://127.0.0.1:{broker.port}', NO_PROXY='', no_proxy='')
    env.update(pol.get('environment', {}))
    for w in fs['write'][:1]: env['PWD'] = w
    target = [HERE + '/probe'] if probe else cmd
    target = [shutil.which(target[0]) or target[0], *target[1:]]
    inner = ['/pbp/exec', str(uid), str(gid), sysnums, *exe_args, '--', *target]
    cwd = fs['write'][0] if fs['write'] else '/'
    lines.append('exec chroot ' + root + ' /usr/bin/env -i ' if False else f'cd {root}{cwd}; exec env -i ' +
                 ' '.join(f"{k}='{v}'" for k, v in env.items()) + f' chroot {root} /bin/false 2>/dev/null || true')
    # chroot and cd in one step: use the launcher through chroot's --userspec-free form
    lines[-1] = f'exec env -i ' + ' '.join(shlex.quote(f'{k}={v}') for k, v in env.items()) + \
        f' /usr/sbin/chroot {root} /pbp/exec ' + ' '.join(shlex.quote(a) for a in inner[1:])
    lines.insert(-1, 'echo PBP_SETUP_DONE $(date +%s%N) >&2')
    script = '\n'.join(lines)
    spec = {'root': root, 'mkdirs': sorted(set(fs['list']) | {os.path.dirname(f) for f in files} | {os.path.dirname(f) for f in fs['devices']}),
            'binds': files + fs['devices'], 'devices': fs['devices'], 'writes': fs['write'], 'proc': fs['proc'],
            'launcher': HERE + '/pbp-exec', 'cgroups': cg, 'cwd': cwd, 'args': inner[1:], 'env': env}
    json.dump(spec, open(f'/tmp/{user}.json', 'w'))
    ns = ['unshare', '--mount', '--pid', '--fork', '--ipc', '--uts', '--cgroup', '--propagation', 'private']
    if pol['network']['mode'] == 'none': ns.append('--net')
    if not fs['proc']: pass
    t = time.time()
    p = subprocess.run([*ns, sys.executable, '-I', HERE + '/pbp_root.py', f'/tmp/{user}.json'], capture_output=True, text=True, timeout=pol['limits']['seconds'])
    end = time.time(); m = re.search(r'PBP_SETUP_DONE (\d+)', p.stderr)
    if m: T['namespaces and root'] = int(m[1]) / 1e9 - t; T['run'] = end - int(m[1]) / 1e9
    else: T['namespaces, root and run'] = end - t
    p = subprocess.CompletedProcess(p.args, p.returncode, p.stdout, re.sub(r'PBP_SETUP_DONE \d+\n', '', p.stderr))
    t = time.time()
    for r in ipt: subprocess.run(['iptables', '-D', 'OUTPUT', '-m', 'owner', '--uid-owner', str(uid), *r])
    for d in cg: os.rmdir(d)
    os.rmdir(root); os.remove(f'/tmp/{user}.json'); subprocess.run(['userdel', user]); T['clean up'] = time.time() - t
    print(p.stdout, end=''); print(p.stderr[-2000:], end='', file=sys.stderr)
    if broker: print('broker:', broker.log)
    print('exit', p.returncode, '| ' + ', '.join(f'{k} {v*1000:.0f} ms' for k, v in T.items()))
    return p, T

if __name__ == '__main__':
    a = sys.argv[1:]
    if a[0] == 'trace':
        name = a[1]; i = a.index('--'); opts = a[2:i]
        writes = [opts[j + 1] for j, o in enumerate(opts) if o == '--write']
        hosts = [opts[j + 1] for j, o in enumerate(opts) if o == '--host']
        envs = [opts[j + 1] for j, o in enumerate(opts) if o == '--env']
        trace(name, a[i + 1:], writes, hosts, envs)
    elif a[0] == 'run':
        cmd = a[a.index('--cmd') + 1:] if '--cmd' in a else None
        off = a[a.index('--off') + 1].split(',') if '--off' in a else ()
        run(a[1], probe='--probe' in a, cmd=cmd, off=off)

