"""Inside the new namespaces: build the policy's root with mount syscalls, then chroot and exec the launcher."""
import ctypes, json, os, sys, time
libc = ctypes.CDLL(None, use_errno=True)
MS_RDONLY, MS_REMOUNT, MS_BIND = 1, 32, 4096
def mount(src, dst, fs, flags, data=None):
    if libc.mount(src.encode() if src else None, dst.encode(), fs.encode() if fs else None, flags, data.encode() if data else None):
        e = ctypes.get_errno(); raise OSError(e, f'mount {src} {dst}: {os.strerror(e)}')
spec = json.load(open(sys.argv[1]))
root = spec['root']
mount('pbp', root, 'tmpfs', 0, 'size=1m,mode=755')
for d in spec['mkdirs']: os.makedirs(root + d, exist_ok=True)
for f in spec['binds']:
    open(root + f, 'a').close(); mount(f, root + f, None, MS_BIND)
    if f not in spec['devices']: mount(None, root + f, None, MS_BIND | MS_REMOUNT | MS_RDONLY)
for w in spec['writes']: os.makedirs(root + w, exist_ok=True); mount(w, root + w, None, MS_BIND)
if spec['proc']: os.makedirs(root + '/proc', exist_ok=True); mount('proc', root + '/proc', 'proc', 0, 'hidepid=2')
os.makedirs(root + '/pbp', exist_ok=True); open(root + '/pbp/exec', 'a').close()
mount(spec['launcher'], root + '/pbp/exec', None, MS_BIND)
mount(None, root, None, MS_BIND | MS_REMOUNT | MS_RDONLY)
for c in spec['cgroups']: open(c + '/cgroup.procs', 'w').write(str(os.getpid()))
print('PBP_SETUP_DONE', time.time_ns(), file=sys.stderr, flush=True)
os.chroot(root); os.chdir(spec['cwd'])
os.execve('/pbp/exec', ['/pbp/exec', *spec['args']], spec['env'])

