// pbp-exec: the last step of a process behaviour policy, run inside the new root.
// Applies Landlock (filesystem), drops to an unprivileged uid with no capabilities,
// sets no_new_privs, installs a seccomp allowlist, then execs the target.
// usage: pbp-exec UID GID SYSCALLS(comma list|-) [ro:PATH|rx:PATH|rw:PATH|port:N ...] -- cmd args
#define _GNU_SOURCE
#include <linux/landlock.h>
#include <linux/seccomp.h>
#include <linux/filter.h>
#include <linux/audit.h>
#include <sys/syscall.h>
#include <sys/prctl.h>
#include <grp.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <stddef.h>
#include <errno.h>
#include <sys/stat.h>
/* newer than this machine's headers; the kernel reports Landlock ABI 7 */
#define LL_IOCTL_DEV (1ULL << 15)
#define LL_SCOPE_ABSTRACT_UNIX_SOCKET (1ULL << 0)
#define LL_SCOPE_SIGNAL (1ULL << 1)
#define LL_NET_BIND_TCP (1ULL << 0)
#define LL_NET_CONNECT_TCP (1ULL << 1)
#define LL_RULE_NET_PORT 2
struct ll_ruleset_attr { __u64 handled_access_fs, handled_access_net, scoped; };
struct ll_net_port_attr { __u64 allowed_access; __u64 port; } __attribute__((packed));

static void die(const char *m){ perror(m); _exit(126); }

int main(int argc, char **argv){
  if (argc < 5) { fprintf(stderr, "usage\n"); return 2; }
  uid_t uid = atoi(argv[1]); gid_t gid = atoi(argv[2]); char *sys = argv[3];
  int i = 4;
  __u64 ro = LANDLOCK_ACCESS_FS_READ_FILE | LANDLOCK_ACCESS_FS_READ_DIR;
  __u64 all = ro | LANDLOCK_ACCESS_FS_EXECUTE | LANDLOCK_ACCESS_FS_WRITE_FILE | LANDLOCK_ACCESS_FS_REMOVE_DIR | LANDLOCK_ACCESS_FS_REMOVE_FILE |
    LANDLOCK_ACCESS_FS_MAKE_CHAR | LANDLOCK_ACCESS_FS_MAKE_DIR | LANDLOCK_ACCESS_FS_MAKE_REG | LANDLOCK_ACCESS_FS_MAKE_SOCK |
    LANDLOCK_ACCESS_FS_MAKE_FIFO | LANDLOCK_ACCESS_FS_MAKE_BLOCK | LANDLOCK_ACCESS_FS_MAKE_SYM | LANDLOCK_ACCESS_FS_REFER |
    LANDLOCK_ACCESS_FS_TRUNCATE | LL_IOCTL_DEV;
  struct ll_ruleset_attr ra = { .handled_access_fs = all, .handled_access_net = LL_NET_BIND_TCP | LL_NET_CONNECT_TCP,
    .scoped = LL_SCOPE_ABSTRACT_UNIX_SOCKET | LL_SCOPE_SIGNAL };
  int rs = syscall(SYS_landlock_create_ruleset, &ra, sizeof ra, 0);
  if (rs < 0) die("landlock_create_ruleset");
  int noll = 0;
  for (; i < argc && strcmp(argv[i], "--"); i++) {
    if (!strcmp(argv[i], "off:landlock")) { noll = 1; continue; }
    if (!strncmp(argv[i], "port:", 5)) {
      struct ll_net_port_attr np = { .allowed_access = LL_NET_CONNECT_TCP, .port = atoi(argv[i] + 5) };
      if (syscall(SYS_landlock_add_rule, rs, LL_RULE_NET_PORT, &np, 0)) die("port"); continue; }
    int w = !strncmp(argv[i], "rw:", 3), x = !strncmp(argv[i], "rx:", 3); const char *p = argv[i] + 3;
    int fd = open(p, O_PATH | O_CLOEXEC); if (fd < 0) continue;
    struct stat st; fstat(fd, &st);
    struct landlock_path_beneath_attr pb = { .allowed_access = w ? all : x ? (ro | LANDLOCK_ACCESS_FS_EXECUTE) : ro, .parent_fd = fd };
    if (!S_ISDIR(st.st_mode)) pb.allowed_access &= LANDLOCK_ACCESS_FS_EXECUTE | LANDLOCK_ACCESS_FS_READ_FILE |
      LANDLOCK_ACCESS_FS_WRITE_FILE | LANDLOCK_ACCESS_FS_TRUNCATE | LL_IOCTL_DEV;
    if (syscall(SYS_landlock_add_rule, rs, LANDLOCK_RULE_PATH_BENEATH, &pb, 0)) die(p);
    close(fd);
  }
  if (i >= argc) { fprintf(stderr, "no command\n"); return 2; }
  i++;
  if (setgroups(0, NULL) || setresgid(gid, gid, gid) || setresuid(uid, uid, uid)) die("drop uid");
  if (prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0)) die("no_new_privs");
  if (!noll && syscall(SYS_landlock_restrict_self, rs, 0)) die("landlock_restrict_self");
  if (strcmp(sys, "-")) {
    int n = 1; for (char *c = sys; *c; c++) if (*c == ',') n++;
    struct sock_filter *f = calloc(n + 8, sizeof *f); int k = 0;
    f[k++] = (struct sock_filter)BPF_STMT(BPF_LD|BPF_W|BPF_ABS, offsetof(struct seccomp_data, arch));
    f[k++] = (struct sock_filter)BPF_JUMP(BPF_JMP|BPF_JEQ|BPF_K, AUDIT_ARCH_X86_64, 1, 0);
    f[k++] = (struct sock_filter)BPF_STMT(BPF_RET|BPF_K, SECCOMP_RET_KILL_PROCESS);
    f[k++] = (struct sock_filter)BPF_STMT(BPF_LD|BPF_W|BPF_ABS, offsetof(struct seccomp_data, nr));
    int base = k; char *dup = strdup(sys), *tok = strtok(dup, ","); int m = 0; int nrs[600];
    while (tok) { nrs[m++] = atoi(tok); tok = strtok(NULL, ","); }
    for (int j = 0; j < m; j++) f[k++] = (struct sock_filter)BPF_JUMP(BPF_JMP|BPF_JEQ|BPF_K, nrs[j], (__u8)(m - j), 0);
    f[k++] = (struct sock_filter)BPF_STMT(BPF_RET|BPF_K, SECCOMP_RET_ERRNO | EPERM);
    f[k++] = (struct sock_filter)BPF_STMT(BPF_RET|BPF_K, SECCOMP_RET_ALLOW);
    (void)base;
    struct sock_fprog prog = { .len = k, .filter = f };
    if (prctl(PR_SET_SECCOMP, SECCOMP_MODE_FILTER, &prog)) die("seccomp");
  }
  execv(argv[i], argv + i); die("execv");
}

