// probe: tries what a process behaviour policy should forbid, and reports each result.
#define _GNU_SOURCE
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <dirent.h>
#include <signal.h>
#include <sched.h>
#include <sys/ptrace.h>
#include <sys/mount.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/wait.h>
static void r(const char *what, int rc){ printf("%-44s %s\n", what, rc < 0 ? strerror(errno) : "ALLOWED"); }
static int tcp(const char *ip, int port){ int s = socket(AF_INET, SOCK_STREAM, 0); if (s < 0) return -1;
  struct sockaddr_in a = { .sin_family = AF_INET, .sin_port = htons(port) }; inet_pton(AF_INET, ip, &a.sin_addr);
  int rc = connect(s, (void*)&a, sizeof a); int e = errno; close(s); errno = e; return rc; }
int main(void){
  setvbuf(stdout, NULL, _IONBF, 0);
  printf("uid %d, gid %d\n", getuid(), getgid());
  r("read /etc/shadow", open("/etc/shadow", O_RDONLY));
  r("read /etc/passwd", open("/etc/passwd", O_RDONLY));
  r("read /root/.claude (the agent's home)", open("/root/.claude", O_RDONLY|O_DIRECTORY));
  r("write /usr/lib/x (the system)", open("/usr/lib/x", O_WRONLY|O_CREAT, 0644));
